  "sideEffects": [],
  "exports": {
    "./package.json": "./package.json",
    ".": "./src/index.ts",
    "./internal/*": null,
    "./*/index": null,
    "./Bind": "./src/Bind.ts",
    "./Config": "./src/Config.ts",
    "./Contribution": "./src/Contribution.ts",
    "./Hooks": "./src/Hooks.ts",
    "./Host": "./src/Host.ts",
    "./JsonSchema": "./src/JsonSchema.ts",
    "./Kernel": "./src/Kernel.ts",
    "./Keys": "./src/Keys.ts",
    "./Load": "./src/Load.ts",
    "./Manifest": "./src/Manifest.ts",
    "./Plugin": "./src/Plugin.ts",
    "./PluginError": "./src/PluginError.ts",
    "./Plugins": "./src/Plugins.ts",
    "./Resolve": "./src/Resolve.ts",
    "./When": "./src/When.ts",
    "./index": "./src/index.ts"
  },
  "files": [
    "src/**/*.ts",
    "dist/**/*.js",
    "dist/**/*.js.map",
    "dist/**/*.d.ts",
    "dist/**/*.d.ts.map",
    "dist/**/package.json",
    "LICENSE",
    "README.md",
    "CHANGELOG.md",
    "docs/"
